// WsMessage Every text frame on the control channel. A request has `id` + `type`
// (+ `payload`). Its reply has a fresh `id`, `type: "reply"`, `replyTo`
// set to the request id, and either `ok: true` + `payload` or
// `ok: false` + `error`. Requests the peer does not understand are
// answered with error code `UNKNOWN_TYPE` and otherwise ignored, so an
// older peer survives a newer one adding message types.
type WsMessage struct {
	Error   *WsError                `json:"error,omitempty"`
	Id      string                  `json:"id"`
	Ok      *bool                   `json:"ok,omitempty"`
	Payload *map[string]interface{} `json:"payload,omitempty"`
	ReplyTo *string                 `json:"replyTo,omitempty"`
	Type    string                  `json:"type"`
}

